eigen_decomp &lt;- function(x, comps) {

  LV &lt;- eigen(cov(x))
  L &lt;- LV[["values"]][1:comps]
  V &lt;- LV[["vectors"]][ , 1:comps]

  result &lt;- V %*% sweep(t(V), 1, L, "*")

  return(result)

}


