Implied shocks
Implied shocks are the product of the \(n\)th eigenvector and the square root of the \(n\)th eigenvalue (annualized using the square root of time):
\[
\begin{aligned}
\sqrt{\lambda_{n}}\mathbf{v}_{n}
\end{aligned}
\]

roll_shocks &lt;- function(x, width, comp) {

  n_rows &lt;- nrow(x)
  V_ls &lt;- list()
  result_ls &lt;- list()

  for (i in width:n_rows) {

    idx &lt;- max(i - width + 1, 1):i

    LV &lt;- eigen(cov(x[idx, ]))
    L &lt;- LV[["values"]]
    V &lt;- LV[["vectors"]]

    if (i &gt; width) {

      # cosine &lt;- crossprod(V, V_ls[[length(V_ls)]])
      cosine &lt;- similarity(V, V_ls[[length(V_ls)]])
      order &lt;- apply(abs(cosine), 2, which.max) # assumes a one-to-one match between windows
      L &lt;- L[order]
      V &lt;- t(sign(diag(cosine[order, ])) * t(V[ , order]))

    }

    shocks &lt;- sqrt(L[comp]) * V[ , comp]
    V_ls &lt;- append(V_ls, list(V))
    result_ls &lt;- append(result_ls, list(shocks))

  }

  result &lt;- do.call(rbind, result_ls)
  result &lt;- xts::xts(result, zoo::index(x)[width:n_rows])
  colnames(result) &lt;- colnames(x)

  return(result)

}


